from fastapi.responses import HTMLResponse

PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OAE Mission Control</title><style>body{margin:0;background:#05070d;color:#f5f7fb;font-family:Inter,system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:32px}button,input,select{font:inherit}.card{border:1px solid #202d42;background:#090f19;border-radius:16px;padding:20px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.metric{border:1px solid #1d2a3d;border-radius:12px;padding:14px;background:#070c14}.metric small{color:#64738a}.metric strong{display:block;font-size:24px;margin-top:5px}.nav{display:flex;gap:7px;flex-wrap:wrap}.nav button{background:#0a101a;color:#9aa7bb;border:1px solid #24334b;border-radius:9px;padding:9px}.nav button.active{color:white;border-color:#6a7fff}.view{display:none}.view.active{display:block}.input{width:100%;padding:12px;border-radius:10px;border:1px solid #263650;background:#050910;color:white;box-sizing:border-box}.row{display:flex;gap:8px}.primary{background:linear-gradient(110deg,#4d94ff,#9a62ff);border:0;color:white;border-radius:10px;padding:11px 15px;font-weight:700}.job{border:1px solid #1d2a3d;border-radius:12px;padding:14px;margin:8px 0}.muted{color:#748198;font-size:12px}.status{color:#72e6b2}.modal{position:fixed;inset:0;background:#000b;display:grid;place-items:center;padding:18px}.dialog{width:min(460px,100%);background:#0c1320;border:1px solid #2a3850;border-radius:18px;padding:24px;box-sizing:border-box}.hidden{display:none!important}@media(max-width:700px){main{padding:16px}.grid{grid-template-columns:repeat(2,1fr)}.row{flex-direction:column}}</style></head><body><main><header class="card"><strong>OAE</strong><div class="muted">MISSION CONTROL</div></header><div class="nav"><button data-v="overview" class="active">Overview</button><button data-v="missions">Missions</button><button data-v="repositories">Repositories</button><button data-v="intelligence">Intelligence</button><button data-v="security">Security</button><a href="/docs"><button>API docs</button></a><button onclick="signOut()">Sign out</button></div><section id="overview" class="view active"><div class="card"><div class="muted">OAE / GOVERNED AUTONOMY</div><h1>Engineering work should leave evidence, not mystery.</h1><p class="muted">Understand repositories. Create explicit missions. Execute inside defined boundaries. Verify and record the result.</p><button class="primary" onclick="show('missions')">Start a mission</button></div><div class="grid"><div class="metric"><small>MISSIONS</small><strong id="missions">0</strong></div><div class="metric"><small>COMPLETED</small><strong id="completed">0</strong></div><div class="metric"><small>REPOSITORIES</small><strong id="reposCount">0</strong></div><div class="metric"><small>SECURITY</small><strong class="status">ON</strong></div></div><div class="card"><h3>Engineering loop</h3><p class="muted">Understand → Diagnose → Plan → Verify → Record</p><p class="muted">The SaaS interface is an access layer around the engineering core. It does not bypass its governance model.</p></div></section><section id="missions" class="view"><div class="card"><h2>Missions</h2><p class="muted">Run a public repository intelligence mission.</p><div class="row"><input id="url" class="input" placeholder="https://github.com/owner/repository"><select id="op" class="input"><option value="analyze">Analyze repository</option><option value="review">Review findings</option><option value="verify">Verify result</option></select><button class="primary" onclick="runMission()">Run</button></div><div id="notice"></div></div><div id="jobs"></div></section><section id="repositories" class="view"><div class="card"><h2>Repositories</h2><div id="repositoryList" class="muted">No repositories analyzed yet.</div></div></section><section id="intelligence" class="view"><div class="card"><h2>Intelligence</h2><div class="grid"><div class="metric"><small>RI</small><strong>Repository Intelligence</strong></div><div class="metric"><small>EA</small><strong>Engineering Analysis</strong></div><div class="metric"><small>VF</small><strong>Verification</strong></div><div class="metric"><small>GV</small><strong>Governance</strong></div></div></div><div class="card"><h3>Latest result</h3><pre id="latest" class="muted">No result.</pre></div></section><section id="security" class="view"><div class="card"><h2>Security posture</h2><p>API authentication <b>ENFORCED</b></p><p>Tenant isolation <b>ENFORCED</b></p><p>Operation allowlist <b>ENFORCED</b></p><p>Repository writes <b>BLOCKED</b></p><p>Unrestricted shell <b>BLOCKED</b></p><p class="muted">OAE is controlled autonomous engineering, not an unrestricted remote shell.</p></div></section></main><div id="auth" class="modal hidden"><div class="dialog"><h2>Launch developer workspace</h2><p class="muted">Create an isolated OAE tenant. The API key is displayed once.</p><label class="muted">Workspace / team name</label><input id="name" class="input" value="OAE-CORE"><label class="muted">Existing API key</label><input id="key" class="input" placeholder="oae_…"><div class="row" style="margin-top:12px"><button onclick="useKey()">Use API key</button><button class="primary" onclick="createTenant()">Create workspace</button></div><div id="authNotice"></div></div></div><script>let key=localStorage.getItem('oae_api_key')||'';let jobs=[];const $=x=>document.getElementById(x);function show(v){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===v));document.querySelectorAll('[data-v]').forEach(e=>e.classList.toggle('active',e.dataset.v===v));if(key)load()}document.querySelectorAll('[data-v]').forEach(e=>e.onclick=()=>show(e.dataset.v));function headers(){return key?{'Authorization':'Bearer '+key,'Content-Type':'application/json'}:{'Content-Type':'application/json'}}async function api(p,o={}){let r=await fetch(p,{...o,headers:{...headers(),...(o.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||'Request failed');return d}function esc(v){return String(v??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}async function useKey(){key=$('key').value.trim();if(!key)return;$('authNotice').textContent='Authenticating…';try{await api('/v1/me');localStorage.setItem('oae_api_key',key);$('auth').classList.add('hidden');load()}catch(e){$('authNotice').textContent=e.message;key=''}}async function createTenant(){try{let d=await api('/v1/tenants',{method:'POST',body:JSON.stringify({name:$('name').value.trim()})});key=d.api_key;localStorage.setItem('oae_api_key',key);$('auth').classList.add('hidden');alert('Copy your API key now: '+key);load()}catch(e){$('authNotice').textContent=e.message}}function signOut(){localStorage.removeItem('oae_api_key');key='';$('auth').classList.remove('hidden')}async function runMission(){let url=$('url').value.trim().replace(/\.git$/,'');if($('op').value==='analyze'&&!/^https:\/\/github\.com\/[^/]+\/[^/]+\/?$/.test(url)){$('notice').textContent='Use a public GitHub repository URL.';return}try{let op=$('op').value;await api('/v1/jobs',{method:'POST',body:JSON.stringify({operation:op,payload:op==='analyze'?{repository_url:url}:{success:true,checks:['control-plane submission']}})});$('url').value='';$('notice').textContent='Mission queued.';load()}catch(e){$('notice').textContent=e.message}}async function load(){if(!key)return;try{jobs=await api('/v1/jobs');$('missions').textContent=jobs.length;$('completed').textContent=jobs.filter(j=>j.status==='completed').length;let rs={};jobs.forEach(j=>{if(j.result?.repository)rs[j.result.repository]=j.result});$('reposCount').textContent=Object.keys(rs).length;$('jobs').innerHTML=jobs.map(j=>'<div class="job"><b>'+esc(j.operation)+'</b> · <span>'+esc(j.status)+'</span><div class="muted">'+esc(j.result?.repository||j.payload?.repository_url||'')+'</div><pre class="muted">'+esc(JSON.stringify(j.result||{},null,2))+'</pre></div>').join('')||'<div class="card muted">No missions yet.</div>';$('repositoryList').innerHTML=Object.values(rs).map(r=>'<div class="job"><b>'+esc(r.repository)+'</b><div class="muted">'+(r.files??0)+' files · '+(r.python_files??0)+' Python · '+(r.test_files??0)+' tests · branch '+esc(r.default_branch||'—')+'</div></div>').join('')||'No repositories analyzed yet.';let last=jobs.find(j=>j.result);if(last)$('latest').textContent=JSON.stringify(last.result,null,2)}catch(e){if(/401|Invalid|Bearer/.test(e.message)){key='';localStorage.removeItem('oae_api_key');$('auth').classList.remove('hidden')}}}if(!key)$('auth').classList.remove('hidden');else load();setInterval(load,12000)</script></body></html>'''


def page() -> HTMLResponse:
    return HTMLResponse(PAGE)
